        int64_t vector_count = total / 4;
        cute_sigmoid_float4_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(x_contiguous.data_ptr<float>()),
            reinterpret_cast<float4*>(output.data_ptr<float>()),
            vector_count,
            total);
    } else if (x_contiguous.scalar_type() == at::kHalf) {
        int64_t vector_count = total / 2;
        cute_sigmoid_half2_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const __half2*>(x_contiguous.data_ptr<at::Half>()),
            reinterpret_cast<__half2*>(output.data_ptr<at::Half>()),
            vector_count,
            total);
    } else {
        int64_t vector_count = total / 2;
        cute_sigmoid_bfloat162_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const __nv_bfloat162*>(x_contiguous.data_ptr<at::BFloat16>()),
            reinterpret_cast<__nv_bfloat162*>(output.data_ptr<at::BFloat16>()),
            vector_count,
            total);
    }

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE sigmoid kernel launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid(x)

